        if (rooms.containsKey(name)) return "error: room " + name + " exists";
        rooms.put(name, new Room(name, capacity));
        return "room " + name + " for " + capacity;
    }

    String take(Room r, int start, int end) {
        int id = nextId++;
        r.bookings.put(id, new int[] {start, end});
        where.put(id, r.name);
        return "booking " + id + ": " + r.name;
    }

    String book(int size, int start, int end) {
