        Room r = rooms.get(name);
        if (r == null) return List.of("error: no room " + name);
        List<int[]> rows = new ArrayList<>();
        for (Map.Entry<Integer, int[]> e : r.bookings.entrySet()) rows.add(new int[] {e.getValue()[0], e.getValue()[1], e.getKey()});
        rows.sort((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] != b[1] ? a[1] - b[1] : a[2] - b[2]);
        List<String> out = new ArrayList<>();
        for (int[] x : rows) out.add(String.format("%d: %02d:%02d-%02d:%02d", x[2], x[0] / 60, x[0] % 60, x[1] / 60, x[1] % 60));
        return out.isEmpty() ? List.of(name + ": free all day") : out;
    }
}

