import java.util.*;

class Room {
    final String name;
    final int capacity;
    final Map<Integer, int[]> bookings = new HashMap<>();   // id -> {start, end}

    Room(String name, int capacity) { this.name = name; this.capacity = capacity; }

    boolean isFree(int start, int end) {
        for (int[] b : bookings.values()) if (!(end <= b[0] || b[1] <= start)) return false;
        return true;
    }
}

class Scheduler {
    final Map<String, Room> rooms = new HashMap<>();
    final Map<Integer, String> where = new HashMap<>();
    int nextId = 1;

    String addRoom(String name, int capacity) {
        if (rooms.containsKey(name)) return "error: room " + name + " exists";
        rooms.put(name, new Room(name, capacity));
        return "room " + name + " for " + capacity;
    }

    String take(Room r, int start, int end) {
        int id = nextId++;
        r.bookings.put(id, new int[] {start, end});
        where.put(id, r.name);
        return "booking " + id + ": " + r.name;
    }

    String book(int size, int start, int end) {
        Room best = null;
        for (Room r : rooms.values()) {
            if (r.capacity < size || !r.isFree(start, end)) continue;
            if (best == null || r.capacity < best.capacity || (r.capacity == best.capacity && r.name.compareTo(best.name) < 0)) best = r;
        }
        return best == null ? "error: no room free" : take(best, start, end);
    }

    String cancel(int id) {
        String name = where.remove(id);
        if (name == null) return "error: no booking " + id;
        rooms.get(name).bookings.remove(id);
        return "cancelled " + id;
    }

    List<String> agenda(String name) {
        Room r = rooms.get(name);
        if (r == null) return List.of("error: no room " + name);
        List<int[]> rows = new ArrayList<>();
        for (Map.Entry<Integer, int[]> e : r.bookings.entrySet()) rows.add(new int[] {e.getValue()[0], e.getValue()[1], e.getKey()});
